      weakFiber: 'நார்ச்சத்து குறைவு — WHO நாளொன்றுக்கு குறைந்தது 25g பரிந்துரைக்கிறது',
      weakProtein: 'புரதம் மிகக் குறைவு',
      weakProcessingNova: 'இது NOVA {nova} (அல்ட்ரா-பதப்படுத்தப்பட்ட) வகையில் உள்ளது',
