      'advice.sugars': 'சர்க்கரை இல்லாத அல்லது குறைந்த சர்க்கரை மாற்றுகளைப் பாருங்கள்.',
      'advice.fats': 'குறைந்த நிறைவுற்ற கொழுப்புள்ள மாற்றுகளைத் தேர்வு செய்யுங்கள், உதாரணமாக பேக்டு வகைகள்.',
      'advice.sodium': 'குறைந்த சோடியம் வகைகளை முயற்சிக்கவும் அல்லது மசாலாவால் சுவை கூட்டவும்.',
      'advice.calories': 'சிறிய அளவு அல்லது இலகுவான மாற்று சிறந்தது.',
      'advice.processing': 'குறைந்த பொருட்கள் கொண்ட முழு-உணவு மாற்றுகள் ஆரோக்கியமானவை.',
      'advice.additives': 'சிறிய, அடையாளம் காணக்கூடிய பொருட்கள் பட்டியலுள்ள தயாரிப்புகள் சிறந்தவை.',
      'advice.fiber': 'முழு தானியங்கள், பழங்கள் அல்லது காய்கறிகள் சேர்த்தால் நார்ச்சத்து இலக்கை அடையலாம்.',
      'advice.protein': 'சமச்சீர் உணவுக்கு இதைப் புரதம் நிறைந்த உணவுடன் சேர்த்து உண்ணுங்கள்.',
