      'one small glass (200 ml)': 'ஒரு சிறிய டம்ளர் (200 ml)',
      'one bowl (about 30 g)': 'ஒரு கிண்ணம் (சுமார் 30 g)',
      'a small serving': 'ஒரு சிறிய சர்விங்',
      'Ingredient list not available to verify against this fast.': 'இந்த விரதத்துக்குச் சரிபார்க்க பொருட்கள் பட்டியல் இல்லை.',
      'No conflicting ingredients detected for this fasting profile.': 'இந்த விரத சுயவிவரத்துக்கு முரணான பொருட்கள் எதுவும் இல்லை.',
      'Very high sodium: {0} mg ({1}% of daily reference).': 'சோடியம் மிக அதிகம்: {0} mg (தினசரி அளவில் {1}%).',
      'High sodium: {0} mg ({1}% of daily reference).': 'சோடியம் அதிகம்: {0} mg (தினசரி அளவில் {1}%).',
      'Sodium is {0} mg ({1}% of daily reference).': 'சோடியம் {0} mg (தினசரி அளவில் {1}%).',
