      'Very high {0} caps the overall score.': 'மிக அதிக {0} காரணமாக மொத்த மதிப்பெண் வரம்பிடப்பட்டது.',
      'High {0} limits the overall score.': 'அதிக {0} மொத்த மதிப்பெண்ணை வரம்பிடுகிறது.',
      'Contains {0}, which most {1} profiles do not allow.': 'இதில் {0} உள்ளது; பெரும்பாலான {1} சுயவிவரங்கள் இதை அனுமதிக்காது.',
