      'Jain rules vary by family. Ambiguous additive/flavour sources are shown as Depends/Unknown.': 'జైన నియమాలు కుటుంబాన్ని బట్టి మారతాయి. అస్పష్ట యాడిటివ్/ఫ్లేవర్ మూలాలు "ఆధారపడి"/"తెలియదు" గా చూపుతాం.',
