      'Low fibre — may not aid digestion.': 'ఫైబర్ తక్కువ — జీర్ణానికి సహాయపడకపోవచ్చు.',
      'Reasonable for older adults in moderate portions.': 'పరిమిత పోర్షన్లలో వృద్ధులకు ఫర్వాలేదు.',
