    data: { title: 'ಡೇಟಾ & ನಂಬಿಕೆ', source: 'ಮೂಲ', lastUpdated: 'ಕೊನೆಯ ಅಪ್‌ಡೇಟ್', completeness: 'ಡೇಟಾ ಪೂರ್ಣತೆ', fssai: 'FSSAI ಪರವಾನಗಿ', notFound: 'ಲೇಬಲ್‌ನಲ್ಲಿ ಸಿಗಲಿಲ್ಲ', reportCorrect: 'ಈ ಡೇಟಾವನ್ನು ವರದಿ ಮಾಡಿ ಅಥವಾ ಸರಿಪಡಿಸಿ', high: 'ಹೆಚ್ಚು ನಂಬಿಕೆ', medium: 'ಮಧ್ಯಮ ನಂಬಿಕೆ', low: 'ಕಡಿಮೆ ನಂಬಿಕೆ', fssaiHint: 'ಪರವಾನಗಿ/ನೋಂದಣಿ ಸ್ಥಿತಿ — ಆರೋಗ್ಯ ಅನುಮೋದನೆ ಅಲ್ಲ.', correctedBanner: 'ಈ ಉತ್ಪನ್ನದ ಡೇಟಾದಲ್ಲಿ ZOCO ಸಮೀಕ್ಷೆಯಿಂದ ದೃಢೀಕರಿಸಿದ ತಿದ್ದುಪಡಿ ಇದೆ.', correctedOn: 'ಸಮೀಕ್ಷೆ', communityNote: 'ಡೇಟಾ Open Food Facts ಸಮುದಾಯದಿಂದ ಬರುತ್ತದೆ; ಅಪೂರ್ಣವಿರಬಹುದು. ತಿದ್ದುಪಡಿಗಳು ಹಂಚಿಕೆಯ ಡೇಟಾಬೇಸ್ ಅನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡುತ್ತವೆ.' },
